  // Partner* child models), so these are safe/additive for `prisma db push`.
  //
  // The optional partner ACCOUNT this user logs in as to see their partner portal
  // (opposite of ReferralPartner.user). A user is a partner when this is set.
  referralPartner            ReferralPartner?    @relation("PartnerAccount")
  // The durable attachment binding THIS customer to the agency/KOL that referred
  // them, for the life of the account (opposite of PartnerCustomer.customer).
  partnerAttachment          PartnerCustomer?    @relation("PartnerAttachment")
  // Every commission accrued on this customer's charges (opposite of
  // PartnerCommission.customer). Distinct from the peer-referral wallet bonus.
  partnerCommissions         PartnerCommission[] @relation("PartnerCommissions")
}

