"use client";

import { useState, useTransition } from "react";
import {
  adminCreatePartner,
  adminUpdatePartner,
  adminAttachCustomer,
  adminDetachCustomer,
  adminSettlePartnerCommission,
} from "@/lib/actions-partner";

function Msg({ msg }: { msg: { ok?: boolean; error?: string } | null }) {
  if (!msg) return null;
  if (msg.error)
    return (
      <div className="rounded-lg border border-red-500/30 bg-red-500/10 px-3 py-2 text-sm text-red-400">
        {msg.error}
      </div>
    );
  return (
    <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">
      Saved.
    </div>
  );
}

// ---------- Create partner ----------

export function CreatePartnerForm() {
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  const [pending, start] = useTransition();

  return (
    <form
      action={(fd) =>
        start(async () => {
          const res = await adminCreatePartner(null, fd);
          setMsg(res);
          if (res.ok) (document.getElementById("create-partner-form") as HTMLFormElement)?.reset();
        })
      }
      id="create-partner-form"
      className="space-y-3"
    >
      <Msg msg={msg} />
      <div className="grid gap-3 sm:grid-cols-2">
        <div>
          <label className="label">Partner / agency name</label>
          <input name="name" className="input w-full" placeholder="Acme Studio" required />
        </div>
        <div>
          <label className="label">Referral code</label>
          <input name="code" className="input w-full font-mono" placeholder="ACME" required />
        </div>
        <div>
          <label className="label">Commission rate (%)</label>
          <input
            name="commissionRatePct"
            type="number"
            min="0.5"
            max="90"
            step="0.5"
            defaultValue="20"
            className="input w-full"
            required
          />
        </div>
        <div>
          <label className="label">Contact email (optional)</label>
          <input name="contactEmail" type="email" className="input w-full" placeholder="ops@acme.com" />
        </div>
        <div className="sm:col-span-2">
          <label className="label">Link login account by email (optional)</label>
          <input name="linkEmail" type="email" className="input w-full" placeholder="Existing user email for the partner portal" />
        </div>
      </div>
      <button className="btn-primary" disabled={pending}>
        {pending ? "Creating…" : "Create partner"}
      </button>
    </form>
  );
}

// ---------- Rate + status ----------

export function PartnerRateControls({
  id,
  rate,
  status,
}: {
  id: string;
  rate: number;
  status: string;
}) {
  const [value, setValue] = useState(String(rate));
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  const [pending, start] = useTransition();

  return (
    <div className="space-y-2">
      <Msg msg={msg} />
      <div className="flex flex-wrap items-end gap-2">
        <div>
          <label className="label">Commission rate (%)</label>
          <input
            className="input w-28"
            type="number"
            min="0.5"
            max="90"
            step="0.5"
            value={value}
            onChange={(e) => setValue(e.target.value)}
          />
        </div>
        <button
          className="btn-secondary"
          disabled={pending}
          onClick={() =>
            start(async () => setMsg(await adminUpdatePartner(id, { commissionRatePct: Number(value) })))
          }
        >
          Save rate
        </button>
        <button
          className={status === "ACTIVE" ? "btn-danger" : "btn-primary"}
          disabled={pending}
          onClick={() =>
            start(async () =>
              setMsg(await adminUpdatePartner(id, { status: status === "ACTIVE" ? "PAUSED" : "ACTIVE" }))
            )
          }
        >
          {status === "ACTIVE" ? "Pause partner" : "Reactivate"}
        </button>
      </div>
      <p className="text-[11px] text-slate-500">
        Rate changes apply to FUTURE charges only — already-accrued commission keeps the rate it was
        earned at. Pausing stops new commission accruing.
      </p>
    </div>
  );
}

// ---------- Attach customer ----------

export function AttachCustomerForm({ partnerId }: { partnerId: string }) {
  const [email, setEmail] = useState("");
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  const [pending, start] = useTransition();

  return (
    <div className="space-y-2">
      <Msg msg={msg} />
      <div className="flex flex-wrap items-end gap-2">
        <div className="min-w-0 flex-1">
          <label className="label">Attach customer by email</label>
          <input
            className="input w-full"
            type="email"
            placeholder="customer@example.com"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
        </div>
        <button
          className="btn-primary"
          disabled={pending || !email.trim()}
          onClick={() =>
            start(async () => {
              const res = await adminAttachCustomer(partnerId, email);
              setMsg(res);
              if (res.ok) setEmail("");
            })
          }
        >
          {pending ? "Attaching…" : "Attach"}
        </button>
      </div>
      <p className="text-[11px] text-slate-500">
        The attachment is permanent — a customer belongs to exactly one partner for life.
      </p>
    </div>
  );
}

export function DetachCustomerButton({ attachmentId }: { attachmentId: string }) {
  const [pending, start] = useTransition();
  const [error, setError] = useState<string | null>(null);
  return (
    <div className="flex flex-col items-end gap-1">
      <button
        className="btn-danger py-1 text-xs"
        disabled={pending}
        onClick={() => {
          if (!confirm("Detach this customer? Future charges will no longer earn commission. Past commission is kept.")) return;
          start(async () => {
            const res = await adminDetachCustomer(attachmentId);
            if (res?.error) setError(res.error);
          });
        }}
      >
        Detach
      </button>
      {error && <span className="text-[11px] text-red-400">{error}</span>}
    </div>
  );
}

// ---------- Settle commission ----------

export function SettleCommissionButton({
  partnerId,
  outstandingLabel,
  disabled,
}: {
  partnerId: string;
  outstandingLabel: string;
  disabled: boolean;
}) {
  const [pending, start] = useTransition();
  const [msg, setMsg] = useState<{ ok?: boolean; error?: string } | null>(null);
  return (
    <div className="space-y-2">
      <Msg msg={msg} />
      <button
        className="btn-primary"
        disabled={pending || disabled}
        onClick={() => {
          if (!confirm(`Mark ${outstandingLabel} of accrued commission as PAID? This records an off-wallet settlement.`)) return;
          start(async () => setMsg(await adminSettlePartnerCommission(partnerId)));
        }}
      >
        {pending ? "Settling…" : `Mark ${outstandingLabel} paid`}
      </button>
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge } from "@/components/ui/primitives";
import { formatMoney, currentCurrency } from "@/lib/tax";
import { CreatePartnerForm } from "@/components/admin/PartnerControls";

export const dynamic = "force-dynamic";

export default async function AdminPartnersPage() {
  await requireArea("billing");

  const [partners, currency] = await Promise.all([
    db.referralPartner.findMany({
      orderBy: { createdAt: "desc" },
      take: 500,
      include: {
        user: { select: { email: true } },
        _count: { select: { customers: true } },
      },
    }),
    currentCurrency(),
  ]);

  // Commission totals per partner, by status (bounded to the listed partners).
  const totals = await Promise.all(
    partners.map((p) =>
      db.partnerCommission.groupBy({
        by: ["status"],
        where: { partnerId: p.id },
        _sum: { amountCents: true },
      })
    )
  );
  const sumFor = (i: number, status: string) =>
    totals[i].find((t) => t.status === status)?._sum.amountCents ?? 0;

  const grandOutstanding = partners.reduce((s, _p, i) => s + sumFor(i, "ACCRUED"), 0);
  const grandPaid = partners.reduce((s, _p, i) => s + sumFor(i, "PAID"), 0);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Partners (KOL / Agency)"
        sub="Agencies and creators earn a lifetime commission on every charge their referred customers make. Manage partners, rates and settlements here."
      />

      <div className="grid gap-4 sm:grid-cols-3">
        <div className="card">
          <p className="section-label mb-1">Partners</p>
          <p className="text-2xl font-bold">{partners.length}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Accrued (unpaid)</p>
          <p className="text-2xl font-bold">{formatMoney(grandOutstanding, currency)}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Settled / paid</p>
          <p className="text-2xl font-bold">{formatMoney(grandPaid, currency)}</p>
        </div>
      </div>

      <div className="card space-y-4">
        <p className="section-label">Add a partner</p>
        <CreatePartnerForm />
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">All partners</p>
        {partners.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No partners yet. Add one above.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[820px]">
            <thead>
              <tr>
                <th>Partner</th>
                <th>Code</th>
                <th className="text-right">Rate</th>
                <th className="text-right">Customers</th>
                <th className="text-right">Accrued</th>
                <th className="text-right">Paid</th>
                <th>Status</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {partners.map((p, i) => (
                <tr key={p.id}>
                  <td>
                    <div className="text-slate-200">{p.name}</div>
                    <div className="text-xs text-slate-500">{p.user?.email ?? p.contactEmail ?? "no login"}</div>
                  </td>
                  <td className="font-mono text-brand-200">{p.code}</td>
                  <td className="text-right font-mono">{p.commissionRatePct}%</td>
                  <td className="text-right font-mono">{p._count.customers}</td>
                  <td className="text-right font-mono">{formatMoney(sumFor(i, "ACCRUED"), currency)}</td>
                  <td className="text-right font-mono text-emerald-400">
                    {formatMoney(sumFor(i, "PAID"), currency)}
                  </td>
                  <td>
                    <Badge tone={p.status === "ACTIVE" ? "green" : "slate"}>{p.status.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right">
                    <Link href={`/admin/partners/${p.id}`} className="text-brand-300 hover:underline">
                      Manage
                    </Link>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, timeAgo } from "@/components/ui/primitives";
import { formatMoney, currentCurrency } from "@/lib/tax";
import { computePartnerSummary } from "@/lib/partner-commission";
import {
  PartnerRateControls,
  AttachCustomerForm,
  DetachCustomerButton,
  SettleCommissionButton,
} from "@/components/admin/PartnerControls";

export const dynamic = "force-dynamic";

const KIND_TONE: Record<string, "brand" | "amber" | "slate"> = {
  ORDER: "brand",
  RENEWAL: "amber",
  CHARGE: "slate",
};

export default async function AdminPartnerDetailPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  await requireArea("billing");
  const { id } = await params;

  const partner = await db.referralPartner.findUnique({
    where: { id },
    include: { user: { select: { email: true, name: true } } },
  });
  if (!partner) notFound();

  const [summary, currency, customers, commissions] = await Promise.all([
    computePartnerSummary(id),
    currentCurrency(),
    db.partnerCustomer.findMany({
      where: { partnerId: id },
      orderBy: { attachedAt: "desc" },
      take: 500,
      include: { customer: { select: { name: true, email: true } } },
    }),
    db.partnerCommission.findMany({
      where: { partnerId: id },
      orderBy: { createdAt: "desc" },
      take: 200,
      include: {
        customer: { select: { email: true } },
        invoice: { select: { number: true } },
      },
    }),
  ]);

  // Per-customer lifetime commission (bounded to listed customers).
  const perCustomer = await Promise.all(
    customers.map((c) =>
      db.partnerCommission.aggregate({
        where: { partnerId: id, customerId: c.customerId },
        _sum: { amountCents: true },
      })
    )
  );

  const s = summary!;

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-2 text-sm text-slate-400">
        <Link href="/admin/partners" className="text-brand-300 hover:underline">
          Partners
        </Link>
        <span>/</span>
        <span className="text-slate-200">{partner.name}</span>
      </div>

      <PageHeader
        title={partner.name}
        sub={`Code ${partner.code} · ${partner.user?.email ?? partner.contactEmail ?? "no login linked"}`}
      />

      <div className="grid gap-4 sm:grid-cols-4">
        <div className="card">
          <p className="section-label mb-1">Customers</p>
          <p className="text-2xl font-bold">{s.customerCount}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Lifetime commission</p>
          <p className="text-2xl font-bold">{formatMoney(s.lifetimeCents, currency)}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Accrued (unpaid)</p>
          <p className="text-2xl font-bold text-brand-300">{formatMoney(s.outstandingCents, currency)}</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Paid out</p>
          <p className="text-2xl font-bold text-emerald-400">{formatMoney(s.paidCents, currency)}</p>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <div className="card space-y-4">
          <div className="flex items-center justify-between">
            <p className="section-label">Rate &amp; status</p>
            <Badge tone={partner.status === "ACTIVE" ? "green" : "slate"}>
              {partner.status.toLowerCase()}
            </Badge>
          </div>
          <PartnerRateControls id={partner.id} rate={partner.commissionRatePct} status={partner.status} />
        </div>

        <div className="card space-y-4">
          <p className="section-label">Settle commission</p>
          <p className="text-sm text-slate-400">
            Partners are paid off-wallet (bank transfer / invoice). Marking as paid advances the ledger
            without moving any wallet balance.
          </p>
          <SettleCommissionButton
            partnerId={partner.id}
            outstandingLabel={formatMoney(s.outstandingCents, currency)}
            disabled={s.outstandingCents <= 0}
          />
        </div>
      </div>

      <div className="card space-y-4">
        <p className="section-label">Attach a customer</p>
        <AttachCustomerForm partnerId={partner.id} />
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">Attached customers</p>
        {customers.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No customers attached yet.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[640px]">
            <thead>
              <tr>
                <th>Customer</th>
                <th>Attached</th>
                <th className="text-right">Lifetime commission</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {customers.map((c, i) => (
                <tr key={c.id}>
                  <td>
                    <div className="text-slate-200">{c.customer.name || "—"}</div>
                    <div className="text-xs text-slate-500">{c.customer.email}</div>
                  </td>
                  <td className="text-xs text-slate-400" title={c.attachedAt.toISOString()}>
                    {timeAgo(c.attachedAt)}
                  </td>
                  <td className="text-right font-mono">
                    {formatMoney(perCustomer[i]._sum.amountCents ?? 0, currency)}
                  </td>
                  <td className="text-right">
                    <DetachCustomerButton attachmentId={c.id} />
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">Commission ledger</p>
        {commissions.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No commission accrued yet.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[760px]">
            <thead>
              <tr>
                <th>When</th>
                <th>Customer</th>
                <th>Invoice</th>
                <th>Type</th>
                <th className="text-right">Charge (net)</th>
                <th className="text-right">Rate</th>
                <th className="text-right">Commission</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {commissions.map((c) => (
                <tr key={c.id}>
                  <td className="text-xs text-slate-400" title={c.createdAt.toISOString()}>
                    {timeAgo(c.createdAt)}
                  </td>
                  <td className="text-xs text-slate-400">{c.customer.email}</td>
                  <td className="font-mono text-xs text-slate-400">#{c.invoice.number}</td>
                  <td>
                    <Badge tone={KIND_TONE[c.kind] ?? "slate"}>{c.kind.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right font-mono">{formatMoney(c.baseCents, currency)}</td>
                  <td className="text-right font-mono">{c.ratePct}%</td>
                  <td className="text-right font-mono">{formatMoney(c.amountCents, currency)}</td>
                  <td>
                    <Badge tone={c.status === "PAID" ? "green" : c.status === "VOID" ? "slate" : "amber"}>
                      {c.status.toLowerCase()}
                    </Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

