import Link from "next/link";
import { db } from "@/lib/db";
import { requireUser } from "@/lib/auth";
import { Badge, timeAgo } from "@/components/ui/primitives";
import { PortalHero } from "@/components/portal/PortalHero";
import { formatMoney, currentCurrency } from "@/lib/tax";
import { computePartnerSummary } from "@/lib/partner-commission";

export const dynamic = "force-dynamic";

const KIND_TONE: Record<string, "brand" | "amber" | "slate"> = {
  ORDER: "brand",
  RENEWAL: "amber",
  CHARGE: "slate",
};

/**
 * Partner-facing portal for an agency / KOL. Shows their attached customers and
 * their accrued / lifetime commission. Only visible to a user whose account is
 * linked to a ReferralPartner (admin links it in /admin/partners); everyone else
 * gets an explainer.
 */
export default async function PartnerPortalPage() {
  const user = await requireUser();

  const partner = await db.referralPartner.findUnique({ where: { userId: user.id } });
  const currency = await currentCurrency();

  if (!partner) {
    return (
      <div className="space-y-6">
        <PortalHero
          variant="refer"
          title="Partner program"
          sub="For agencies & creators who bring clients to Nxeon and earn a lifetime commission on everything they buy."
        />
        <div className="card space-y-2">
          <p className="text-sm text-slate-300">Your account isn&apos;t set up as a partner yet.</p>
          <p className="text-sm text-slate-400">
            The KOL/Agency partner program pays a recurring commission on every service your referred
            customers ever buy or renew — for the life of the customer. If you build sites or bring
            hosting clients, get in touch and we&apos;ll set you up with a partner code.
          </p>
          <p className="text-xs text-slate-500">
            Already refer friends casually? See your{" "}
            <Link href="/dashboard/affiliate" className="text-brand-300 hover:underline">
              affiliate program
            </Link>{" "}
            instead.
          </p>
        </div>
      </div>
    );
  }

  const summary = await computePartnerSummary(partner.id);
  const [customers, commissions] = await Promise.all([
    db.partnerCustomer.findMany({
      where: { partnerId: partner.id },
      orderBy: { attachedAt: "desc" },
      take: 500,
      include: { customer: { select: { name: true, email: true } } },
    }),
    db.partnerCommission.findMany({
      where: { partnerId: partner.id },
      orderBy: { createdAt: "desc" },
      take: 100,
      include: {
        customer: { select: { name: true, email: true } },
        invoice: { select: { number: true } },
      },
    }),
  ]);
  const perCustomer = await Promise.all(
    customers.map((c) =>
      db.partnerCommission.aggregate({
        where: { partnerId: partner.id, customerId: c.customerId },
        _sum: { amountCents: true },
      })
    )
  );

  const s = summary!;
  const appUrl = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/+$/, "");
  const link = `${appUrl}/register?ref=${partner.code}`;

  return (
    <div className="space-y-6">
      <PortalHero
        variant="refer"
        title="Partner dashboard"
        sub="Earn a lifetime commission on every service your referred customers buy or renew."
      >
        <Badge tone={partner.status === "ACTIVE" ? "green" : "slate"}>{partner.status.toLowerCase()}</Badge>
      </PortalHero>

      <div className="card space-y-3">
        <div>
          <p className="section-label mb-1">Your referral link</p>
          <p className="text-sm text-slate-400">
            Send clients here to sign up. Anyone who registers through it is attached to you for life —
            you earn {partner.commissionRatePct}% on everything they ever buy or renew.
          </p>
        </div>
        <input readOnly value={link} className="input w-full font-mono text-xs" />
        <div className="flex flex-wrap items-center gap-2 text-sm text-slate-400">
          <span>Your code:</span>
          <span className="rounded-md border border-white/10 bg-white/[0.04] px-2 py-0.5 font-mono text-brand-200">
            {partner.code}
          </span>
        </div>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div className="card">
          <p className="section-label mb-1">Customers</p>
          <p className="text-2xl font-bold">{s.customerCount}</p>
          <p className="text-xs text-slate-500">attached to you</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Lifetime commission</p>
          <p className="text-2xl font-bold">{formatMoney(s.lifetimeCents, currency)}</p>
          <p className="text-xs text-slate-500">earned all-time</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Accrued</p>
          <p className="text-2xl font-bold text-brand-300">{formatMoney(s.outstandingCents, currency)}</p>
          <p className="text-xs text-slate-500">pending payout</p>
        </div>
        <div className="card">
          <p className="section-label mb-1">Paid out</p>
          <p className="text-2xl font-bold text-emerald-400">{formatMoney(s.paidCents, currency)}</p>
          <p className="text-xs text-slate-500">settled</p>
        </div>
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">Your customers</p>
        {customers.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">
            No customers yet. Share your link above to start earning.
          </p>
        ) : (
          <table className="table-shell mt-2 min-w-[560px]">
            <thead>
              <tr>
                <th>Customer</th>
                <th>Since</th>
                <th className="text-right">Commission earned</th>
              </tr>
            </thead>
            <tbody>
              {customers.map((c, i) => (
                <tr key={c.id}>
                  <td>
                    <div className="text-slate-200">{c.customer.name || "—"}</div>
                    <div className="text-xs text-slate-500">{c.customer.email}</div>
                  </td>
                  <td className="text-xs text-slate-400" title={c.attachedAt.toISOString()}>
                    {timeAgo(c.attachedAt)}
                  </td>
                  <td className="text-right font-mono">
                    {formatMoney(perCustomer[i]._sum.amountCents ?? 0, currency)}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>

      <div className="card overflow-x-auto p-0">
        <p className="section-label px-4 pt-4">Recent commission</p>
        {commissions.length === 0 ? (
          <p className="px-4 py-8 text-sm text-slate-400">No commission accrued yet.</p>
        ) : (
          <table className="table-shell mt-2 min-w-[640px]">
            <thead>
              <tr>
                <th>When</th>
                <th>Customer</th>
                <th>Type</th>
                <th className="text-right">Commission</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {commissions.map((c) => (
                <tr key={c.id}>
                  <td className="text-xs text-slate-400" title={c.createdAt.toISOString()}>
                    {timeAgo(c.createdAt)}
                  </td>
                  <td className="text-xs text-slate-400">{c.customer.name || c.customer.email}</td>
                  <td>
                    <Badge tone={KIND_TONE[c.kind] ?? "slate"}>{c.kind.toLowerCase()}</Badge>
                  </td>
                  <td className="text-right font-mono">{formatMoney(c.amountCents, currency)}</td>
                  <td>
                    <Badge tone={c.status === "PAID" ? "green" : c.status === "VOID" ? "slate" : "amber"}>
                      {c.status.toLowerCase()}
                    </Badge>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

